function levelMaxima(root: TreeNode | null): number[] {
  const best: number[] = [];
  const stack: [TreeNode, number][] = root ? [[root, 0]] : [];
  while (stack.length) {
    const [node, d] = stack.pop()!;
    if (d === best.length) best.push(node.val);
    else best[d] = Math.max(best[d], node.val);
    if (node.right) stack.push([node.right, d + 1]);
    if (node.left) stack.push([node.left, d + 1]);
  }
  return best;
}

