class Solution:
    def levelMaxima(self, root: Optional[TreeNode]) -> List[int]:
        best = []
        stack = [(root, 0)] if root else []
        while stack:
            node, d = stack.pop()
            if d == len(best):
                best.append(node.val)
            else:
                best[d] = max(best[d], node.val)
            if node.right:
                stack.append((node.right, d + 1))
            if node.left:
                stack.append((node.left, d + 1))
        return best

