function levelMaxima(root: TreeNode | null): number[] {
  const out: number[] = [];
  let level: TreeNode[] = root ? [root] : [];
  while (level.length) {
    let top = -Infinity;
    const next: TreeNode[] = [];
    for (const node of level) {
      top = Math.max(top, node.val);
      if (node.left) next.push(node.left);
      if (node.right) next.push(node.right);
    }
    out.push(top);
    level = next;
  }
  return out;
}

